def maximum_top_after_moves(nums,k):
    if k==0:return nums[0]
    if len(nums)==1:return nums[0] if k%2==0 else -1
    candidates=nums[:min(len(nums),k-1)]
    if k<len(nums):candidates.append(nums[k])
    return max(candidates,default=-1)

